CREATE TABLE IF NOT EXISTS gis_phase383_ward_ingestion (dataset_key TEXT PRIMARY KEY, source_url TEXT NOT NULL, fetch_offset BIGINT NOT NULL DEFAULT 0, page_size INTEGER NOT NULL DEFAULT 10, total_loaded BIGINT NOT NULL DEFAULT 0, total_invalid BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'PENDING', last_error TEXT, last_run_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());